-- ==== M349-01 Anmeldung und Verfahrenswahl ====

-- genehmigungsrelevanz
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Auslegung der Schlammwasserbehandlung unterscheidet sich, ob die Teilstrombehandlung als ein fester Bestandteil der Genehmigung der Kläranlage zur Einhaltung der gesetzlichen Überwachungswerte erforderlich ist oder die Schlammwasserbehandlungsanlage lediglich zur Optimierung der Kläranlage (z. B. energetische Optimierung oder Einsparung von Abwasserabgabe) betrieben wird. Trifft ersteres zu, sind ein durchgängiger Betrieb der Schlammwasserbehandlung zu gewährleisten und entsprechende Sicherheiten einzubauen. — printed p.41', verification_note='md-verified 2026-09-05 (§6.3.1, printed p.41) [VC]', verified_at=now() where id='533c6644-a34e-42c0-a3d8-8934042df2bc' and verification_status not in ('verified_against_standard','corrected');

-- verfahren_n_elimination
update public.fields set verification_status='verified_against_standard', verification_quote='Neben dem konventionellen Metabolismus der Nitrifikation/Denitrifikation stehen abgekürzte Prozesswege über Nitrit oder direkt zum elementaren Stickstoff (Deammonifikation) entsprechend dem Stickstoffkreislauf zur Wahl. | Nachfolgend erfolgt eine allgemeine kurze Prozessbeschreibung für die drei zurzeit relevanten biologischen Stickstoffumsetzungsprozesse (Nitrifikation/Denitrifikation, Nitritation/Denitritation und Deammonifikation). — printed p.15', verification_note='md-verified 2026-09-05 (§4.1, printed p.15; the 4 enum options are the 3 printed processes with Deammonifikation split into the printed einstufig/zweistufig variants of §5.3/§5.4) [VC]', verified_at=now() where id='b3e49872-2902-49f5-ae3b-744a633b83ef' and verification_status not in ('verified_against_standard','corrected');

-- schlammsystem
update public.fields set verification_status='verified_against_standard', verification_quote='Für die in Abschnitt 4 beschriebenen biologischen Verfahren der Schlammwasserbehandlung stehen grundsätzlich alle in der Praxis verwendeten Schlammsysteme (Biofilm, Granula, suspendierte Biomasse) zur Verfügung. | Der Begriff „Biofilmverfahren“ wird im Weiteren nur für Verfahren mit industriell gefertigten Aufwuchskörpern (Schwebebettreaktoren (MBBR), Tropfkörper (TK) oder Rotationstauchkörper (RTK) verwendet. | Hybridverfahren, Hybridsystem — printed p.11, p.23', verification_note='md-verified 2026-09-05 (§4.6.1, printed p.23; the 4th option "hybrid" is the §3.1 Begriff "Hybridverfahren, Hybridsystem — Verfahren mit sowohl suspendiertem Schlamm als auch Biofilm oder Granula", printed p.11) [VC]', verified_at=now() where id='1f92797d-47d6-4ef3-9dbc-8b8612c569aa' and verification_status not in ('verified_against_standard','corrected');

-- reaktortyp
update public.fields set verification_status='verified_against_standard', verification_quote='Der Begriff „Biofilmverfahren“ wird im Weiteren nur für Verfahren mit industriell gefertigten Aufwuchskörpern (Schwebebettreaktoren (MBBR), Tropfkörper (TK) oder Rotationstauchkörper (RTK) verwendet. | Grundsätzlich ist damit eine einstufige Deammonifikation mit allen Biofilmverfahren (Tropfkörper, Scheibentauchkörper, getauchtes Festbett und Schwebebett) möglich. | Die beiden Verfahrensvarianten Nitritation mit Denitritation und Nitritation mit Anammox können zweistufig mit einem Ausschwemmreaktor (Rührkessel-Reaktor (CSTR)) als erste Stufe ausgeführt werden. — printed p.23, p.25, p.30', verification_note='md-verified 2026-09-05 (§4.6.1 p.23, §5.1.1 p.25, §5.4.1 p.30; the SBR option is §6.4.3 p.44 "kommen SBR häufig zur Stickstoffelimination aus Prozesswässern der anaeroben Schlammbehandlung zum Einsatz", the Durchlaufsystem option is the Tabelle-2 column head, p.35) [VC]', verified_at=now() where id='6faa21ec-4f01-40a1-9adc-1a5a38df55f7' and verification_status not in ('verified_against_standard','corrected');

-- behandlungsort
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Frage nach einer Behandlung dieses hoch stickstoffhaltigen Teilstroms ist auch darüber zu entscheiden, ob dieser im Nebenstrom separat behandelt oder im Hauptstrom mittels herkömmlicher Nitrifikation/Denitrifikation mitbehandelt werden soll. Diese Entscheidung ist von vielen Einflüssen abhängig und muss individuell getroffen werden. Vor- und Nachteile der Teil- bzw. Hauptstrombehandlung sind in Tabelle 3 qualitativ gegenübergestellt. — printed p.36', verification_note='md-verified 2026-09-05 (§6.1, printed p.36; Tabelle 3 p.36) [VC]', verified_at=now() where id='69ab1715-3bea-4b8b-ad82-5b6e580cb28a' and verification_status not in ('verified_against_standard','corrected');

-- stufigkeit
update public.fields set verification_status='verified_against_standard', verification_quote='Die Deammonifikation kann je nach verfahrenstechnischer Anordnung der Nitritation/anaeroben Ammoniumoxidation entweder einstufig, in einem gemeinsamen Reaktor, oder zweistufig erfolgen. — printed p.17–18', verification_note='md-verified 2026-09-05 (§4.4, printed p.17–18; the sentence sits between Bild 3 (p.17) and the start of §4.5 (p.18), so the section range is cited) [VC]', verified_at=now() where id='8218b474-4cff-4dca-b458-c25620873a6a' and verification_status not in ('verified_against_standard','corrected');

