-- ==== M349-03 Prozessgrundlagen: Kinetik, Hemmungen, Schlammsysteme ====

-- X
update public.fields set verification_status='verified_against_standard', verification_quote='Über die Prozessrate und das zur Verfügung stehende Reaktorvolumen kann der zu erwartende Stoffumsatz berechnet werden (kg/d). Insbesondere für die Bewertung von Raumumsatzleistung ist daher die Angabe der in einem System maximal anreicherbaren Biomasse von elementarer Bedeutung. Da eine direkte Bestimmung der Bakterienanzahl im Kläranlagenbetrieb nicht standardmäßig möglich ist, dient in der Regel der organische Feststoffgehalt als orientierende Größe zur Abschätzung der aktiven Biomasse. — printed p.19', verification_note='md-verified 2026-09-05 (§4.5.1 "Stoffumsatz", printed p.18–19). PARTIAL SUPPORT: the symbol X appears only inside Gl. (3); Gl. (3) is the only numbered equation in this Merkblatt with NO nomenclature block, and the §3.2 Symboltabelle has no X row — the unit g/m3 is inferred from the dimensional closure of Gl. (3) (v in g/(m3·d) = mu_max in 1/d × dimensionless terms × X). [VC]', verified_at=now() where id='5e8e4cbc-f340-4821-ad29-8203617aa16d' and verification_status not in ('verified_against_standard','corrected');

-- v
