-- c_NH3_reaktor
update public.fields set verification_status='verified_against_standard', verification_quote='Für den Regelbetrieb können Konzentrationen $<10 \mathrm{mg} / \mathrm{l} \mathrm{NH} 3-\mathrm{N}$ und $<1 \mathrm{mg} / \mathrm{l} \mathrm{HNO} \mathrm{L}_{2}-\mathrm{N}$ als unkritisch angesehen werden, wobei systemspezifisch auch deutlich höhere Konzentrationen unproblematisch sind (Biofilm z. B. $>100 \mathrm{mg} / \mathrm{l} \mathrm{HNO}_{2}$-N, Cornelius 2008) u. a. aufgrund von Adaptation. | Laborversuche haben gezeigt, dass die Prozessrate weitgehend konstant ist solange $\geq 5 \mathrm{mg} / \mathrm{l} \mathrm{NH}_{4}-\mathrm{N}$ vorhanden sind (keine Substratlimitierung) und die Konzentration an freiem Ammonium $\left(\mathrm{NH}_{3}\right)<20 \mathrm{mg} / \mathrm{l} \mathrm{NH} \mathrm{H}_{3}-\mathrm{N}$ ist (keine Hemmung — printed p.20–21, p.31', verification_note='md-verified 2026-09-05 (§4.5.2 "Nitrifikanten AOB/NOB" p.20–21 gives <10 mg/l NH3-N for Nitrifikanten; §5.4.1 "Beschickung mit Schlammwasser" p.30–32 gives <20 mg/l NH3-N for the Anammox operating window) [VC]', verified_at=now() where id='86b52bc4-903b-404d-bb65-01896337f29e' and verification_status not in ('verified_against_standard','corrected');

-- c_HNO2_reaktor
