-- messung_pH
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 7: Zusammenstellung eingesetzter Online-Messungen nach Verfahrenstyp | Nitri/Deni & ++ & ++ & & & & & + & + & + & $\mathrm{NO}_{\mathrm{x}}$-Messung ist sinnvoll für die C-Quellen-Dosierung | ++ notwendige Messungen. | Der pH-Wert ist immer im Reaktor zu messen. — printed p.52–53', verification_note='md-verified 2026-09-05 (§7.1.1 Tab.7 p.52 — pH is "++" in all three rows — plus the §7.1.2 obligation p.52–53) [VC]', verified_at=now() where id='3d5322bc-db95-4c3a-a0ef-bea7bfef9c1b' and verification_status not in ('verified_against_standard','corrected');

