update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 7: Zusammenstellung eingesetzter Online-Messungen nach Verfahrenstyp | 2-stufige Deammonifikation & ++ & ++ & + & + & & + & + & & + & | 1-stufige Deammonifikation & ++ & ++ & + & + & ++ & ++ & + & + & ++ & $\mathrm{NH}_{4}$-N-Messung nur für Kontrolle | + im Einzelfall sinnvolle Messungen, | ++ notwendige Messungen. — printed p.52', verification_note='md-verified 2026-09-05 (§7.1.1 Tab.7, printed p.52; NH4-N is ++ for the einstufige and + for the zweistufige Deammonifikation, blank for Nitri/Deni — matches is_required=false) [VC]', verified_at=now() where id='fbfc5a65-fd86-4f60-b309-a42e62b90abe' and verification_status not in ('verified_against_standard','corrected');

-- messung_o2
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 7: Zusammenstellung eingesetzter Online-Messungen nach Verfahrenstyp | 1-stufige Deammonifikation & ++ & ++ & + & + & ++ & ++ & + & + & ++ & $\mathrm{NH}_{4}$-N-Messung nur für Kontrolle | Im Bereich niedriger Sauerstoffkonzentrationen ( $\mathrm{O}_{2}<0,5 \mathrm{mg} / \mathrm{l}$ ) wird empfohlen, den Sauerstoffgehalt im Reaktor nicht über die Sauerstoffkonzentration, sondern über die Luftmengen zu regeln, da die Zuverlässigkeit der heute verfügbaren gängigen $\mathrm{O}_{2}$-Sensoren in diesem niedrigen Bereich gering ist. — printed p.51–52', verification_note='md-verified 2026-09-05 (§7.1.1 prose p.51–52 + Tab.7 p.52) [VC]', verified_at=now() where id='f7bb66d0-0bbf-4381-98e9-11872225cbd7' and verification_status not in ('verified_against_standard','corrected');

-- messung_no2
update public.fields set verification_status='verified_against_standard', verification_quote='I Für Anammoxreaktoren kann eine Online-Nitritmessung von Vorteil sein, um toxische Nitritlevel zu vermeiden. Im Bereich niedriger $\mathrm{NO}_{2}$ - N -Konzentrationen ist die Messung auch zuverlässig durchführbar. — printed p.51–52', verification_note='md-verified 2026-09-05 (§7.1.1, printed p.51–52; §7.3.3.2 p.58–60 adds "wird daher bei großen Anlagen ... eine Online-Überwachung der Nitritkonzentration empfohlen") [VC]', verified_at=now() where id='2df36179-64c6-4efb-870b-68aab0daf850' and verification_status not in ('verified_against_standard','corrected');

-- labormessintervall
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn alle notwendigen Online-Messungen vorhanden sind, sollte es ausreichen, die notwendigen Labormessungen ein- bis zweiwöchentlich durchzuführen. Sonst sollten die notwendigen Labormessungen mindestens zweimal die Woche durchgeführt werden. — printed p.52–53', verification_note='md-verified 2026-09-05 (§7.1.2, printed p.52–53; the two printed alternatives are exactly the two encoded enum options) [VC]', verified_at=now() where id='924a10c3-e02d-45c1-b963-1c4d1ede0612' and verification_status not in ('verified_against_standard','corrected');

-- leistungssteigerung_rate
update public.fields set verification_status='verified_against_standard', verification_quote='In der Regel erfolgt die Leistungssteigerung beim Hochfahren um nicht mehr als $3,5 \%$ /d (Verdoppelung der Leistung alle 20 Tage). | I Die Luftzufuhr wird um maximal $3,5 \% /$ d gesteigert; somit entspricht die Mindestzeit für eine Verdoppelung der Leistung 20 Tage. — printed p.55, p.55–56', verification_note='md-verified 2026-09-05 (§7.2.3.1 p.55 + §7.2.3.2 p.55–56; the second occurrence uses "maximal", which supports the encoded block gate CR-015) [VC]', verified_at=now() where id='9eb604da-35d7-45ee-b929-066a5fe5626c' and verification_status not in ('verified_against_standard','corrected');

-- nitrat_anteil_zulauffracht
update public.fields set verification_status='verified_against_standard', verification_quote='- $\mathrm{NO}_{3}$-Bildung < $15 \%$ der N-Fracht im Zulauf. | I Eine Nitrat-Bildung < $15 \%$ der abgebauten N-Fracht bestätigt, dass keine überhöhte Aktivität der NOB im Reaktor vorliegt. — printed p.32, p.55–56', verification_note='md-verified 2026-09-05 (§7.2.3.2 p.55–56 uses "der N-Fracht im Zulauf" — matching this field; §5.4.1 p.32 uses "der abgebauten N-Fracht" for the same 15 % figure. Source-internal denominator inconsistency; gate CR-011 quotes the §5.4.1 wording while the field is Zulauffracht — retag staged. [VC]', verified_at=now() where id='4eafae61-633d-4218-a56c-04eedcfe5781' and verification_status not in ('verified_against_standard','corrected');

-- inbetriebnahme_abgeschlossen
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Inbetriebnahme gilt als abgeschlossen, wenn die Zielleistung mindestens zwei Monate lang erreicht wurde. — printed p.55', verification_note='md-verified 2026-09-05 (§7.2.3.1, printed p.55) [VC]', verified_at=now() where id='b3300563-ec55-4e5f-969d-7675504e4164' and verification_status not in ('verified_against_standard','corrected');

-- impfschlamm_quelle
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Inbetriebnahme des Anammox-Reaktors erfolgt die Befüllung des Reaktors mit Inokulum aus einer anderen Deammonifikationsanlage. Hierbei spielt es keine Rolle, ob es sich beim Impfschlamm um Schlamm einer einstufigen oder zweistufigen Deammonifikation handelt. | Dabei ist die absolute Anammox-Leistung des Schlamms das wichtigste Qualitätskriterium. | Nitrifizierender Schlamm aus einer konventionellen Nitrifikation eignet sich zum Animpfen einer Nitritation. — printed p.54, p.56–57, p.57', verification_note='md-verified 2026-09-05 (§7.2.3.3 p.56–57, §7.2.3.4 p.57, §7.2.1 p.54). CAVEAT on the 4th option "anreicherung": §7.2.3.2 p.55–56 prints "Die Anreicherungsprozedur ist aber sehr aufwendig ... und somit als ungeeignet zu betrachten" — offering it as a plain selectable option is staged as a finding. [VC]', verified_at=now() where id='e86cbed8-132a-484d-b043-6357a9d11b80' and verification_status not in ('verified_against_standard','corrected');

-- ==== M349-08 Nachweis und Zusammenstellung ====

-- n_elimination_erreicht
update public.fields set verification_status='verified_against_standard', verification_quote='Da in der Regel nicht ausreichend Säurekapazität bei der Denitrifikation zurückgewonnen werden kann, muss zusätzlich auch noch Kalkmilch oder Lauge hinzugegeben werden, sollen Wirkungsgrade über $70 \%$ erreicht werden oder eine Kaskadierung vorgesehen werden. | Falls sehr hohe N-Eliminationsgrade ( $>90 \%$ ) erreicht werden sollen, kann die Dosierung von externem Kohlenstoff auch über Onlinemessungen der Nitrat- und Nitrit-Konzentrationen im Reaktor geregelt werden — printed p.28, p.34', verification_note='md-verified 2026-09-05 (§5.5 p.34 + §5.2.2 p.28; the guideline prints process-specific efficiency statements (Nitritation 50–53 % §5.1.2 p.26, N/DN >70 % only with Säurekapazitätsstützung, >90 % with online-controlled C dosing) but NO single required N-elimination figure — the achieved value stays a project result) [VC]', verified_at=now() where id='11d76eae-e449-4a87-896a-50bbeed092cb' and verification_status not in ('verified_against_standard','corrected');

-- entlastung_hauptstrom
update public.fields set verification_status='verified_against_standard', verification_quote='In Bild 7 ist die prozentuale Verbesserung der $\mathrm{N}_{\text {anorg }}$-Ablaufkonzentrationen in Abhängigkeit der Stickstoffelimination in der Schlammwasserbehandlung und der Rückbelastung für zwei Modellkläranlagen mit vorgeschalteter Denitrifikation dargestellt. — printed p.42–43', verification_note='md-verified 2026-09-05 (§6.3.4, printed p.42–43; Bild 7 p.43 is a MODEL calculation ("Modellrechnungen", with the ASM-3 assumptions listed on p.43) — exemplary, not a normative table) [VC]', verified_at=now() where id='384e94b9-9757-4708-a172-60fb56638d80' and verification_status not in ('verified_against_standard','corrected');

